const $=s=>document.querySelector(s);
const featured=['158-eden-on-the-bay','biccardi','184-eden-on-the-bay'];let properties=[],filter='featured';
function render(){const query=$('#property-search').value.trim().toLowerCase();let items=properties.filter(p=>(filter==='all'||(filter==='featured'?featured.includes(p.id):p.region===filter))&&`${p.name} ${p.region}`.toLowerCase().includes(query));if(filter==='featured')items.sort((a,b)=>featured.indexOf(a.id)-featured.indexOf(b.id));const grid=$('#property-grid');grid.replaceChildren();for(const p of items){const card=document.createElement('article');card.className='property-card';const picture=document.createElement('button');picture.className='property-image';picture.setAttribute('aria-label',`Explore ${p.name}`);const img=document.createElement('img');img.src=p.image;img.alt=p.name;img.loading='lazy';picture.append(img);if(p.tag){const tag=document.createElement('span');tag.className='tag';tag.textContent=p.tag.toUpperCase();picture.append(tag)}const arrow=document.createElement('span');arrow.className='image-arrow';arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');picture.append(arrow);picture.addEventListener('click',()=>openProperty(p));const location=document.createElement('p');location.className='property-meta';location.textContent=p.region;const title=document.createElement('h3');const titleBtn=document.createElement('button');titleBtn.textContent=p.name;titleBtn.addEventListener('click',()=>openProperty(p));title.append(titleBtn);const short=document.createElement('p');short.className='property-detail';short.textContent=p.short||'Explore the property & enquire';card.append(picture,location,title,short);grid.append(card)}if(!items.length){const empty=document.createElement('p');empty.className='no-results';empty.textContent=filter==='Langebaan'?'Planning a Langebaan escape? Contact our team for the latest stays.':'No stays match your search. Try another name or view all stays.';grid.append(empty);if(filter==='Langebaan'){const link=document.createElement('a');link.className='button';link.href='mailto:info@capecoaststays.com?subject=Langebaan%20stay%20enquiry';link.textContent='Enquire about Langebaan ↗';grid.append(link)}}$('#result-count').textContent=`${items.length} ${items.length===1?'stay':'stays'} shown`;$('#view-all').hidden=filter==='all';}
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))});render()}
function openProperty(p){$('#dialog-image').src=p.image;$('#dialog-image').alt=p.name;$('#dialog-title').textContent=p.name;$('#dialog-region').textContent=p.region;$('#dialog-description').textContent=p.description||`Discover ${p.name}, part of the Cape Coast Stays collection. Contact the team for the property's latest details and availability.`;$('#dialog-book').href=p.url;$('#dialog-enquire').href='mailto:info@capecoaststays.com?subject='+encodeURIComponent('Stay enquiry: '+p.name);$('#property-dialog').showModal();document.body.style.overflow='hidden'}
const dialog=$('#property-dialog');$('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.style.overflow='');dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>setFilter(b.dataset.filter)));$('#property-search').addEventListener('input',()=>{if($('#property-search').value.trim()&&filter==='featured')setFilter('all');else render()});$('#view-all').addEventListener('click',()=>{setFilter('all');$('#stays').scrollIntoView()});$('#langebaan-link').addEventListener('click',()=>{$('#property-search').value='';setFilter('Langebaan');$('#stays').scrollIntoView()});
fetch('properties.json').then(r=>{if(!r.ok)throw Error('Properties unavailable');return r.json()}).then(data=>{properties=data.map(p=>{return p});render()}).catch(()=>{$('#property-grid').innerHTML='<p>Our collection is available on the booking website. <a class="text-link" href="https://capecoaststays.com/bookyourstay/">Browse all stays ↗</a></p>'});
const menu=$('.menu-toggle');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');$('#navigation').classList.toggle('open',open)});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{$('#navigation').classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')}));
const video=$('#coast-video'),toggle=$('#video-toggle'),motion=matchMedia('(prefers-reduced-motion: reduce)');function videoState(){toggle.textContent=video.paused?'▶':'Ⅱ';toggle.setAttribute('aria-label',video.paused?'Play background video':'Pause background video')}video.addEventListener('play',videoState);video.addEventListener('pause',videoState);toggle.addEventListener('click',()=>{if(video.paused)video.play().catch(videoState);else video.pause()});if(!motion.matches&&!navigator.connection?.saveData)video.play().catch(videoState);motion.addEventListener('change',e=>{if(e.matches)video.pause()});
const reviews=[{quote:"Lovely apartment in a fantastic location, we'll be back",name:'Guy',date:'October 2024'},{quote:'An absolutely fabulous place and location. Michelle was a wonderful host catering to our needs. We will be back!',name:'Andrea',date:'December 2023'},{quote:'A great place and a very professional, friendly host - would book again anytime!',name:'Christian',date:'December 2024'}];let review=0;function updateReview(step){review=(review+step+reviews.length)%reviews.length;const r=reviews[review];$('#quote').textContent='“'+r.quote+'”';$('#review-name').textContent=r.name;$('#review-date').textContent='Airbnb guest · '+r.date;$('#review-page').textContent=String(review+1).padStart(2,'0')+' / 03'}$('#review-prev').addEventListener('click',()=>updateReview(-1));$('#review-next').addEventListener('click',()=>updateReview(1));$('#year').textContent=new Date().getFullYear();
